package edu.riara.edp.week09;
import javafx.application.Application;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;public class BlockedUiDemo extends Application {public void start(Stage s){Label status=new Label("Deliberately blocks UI to illustrate the problem");Button button=new Button("Block for 3 seconds");button.setOnAction(e->{status.setText("Blocked");try{Thread.sleep(3000);}catch(InterruptedException ex){Thread.currentThread().interrupt();}status.setText("Done");});s.setScene(new Scene(new VBox(10,status,button),460,180));s.show();}public static void main(String[]a){launch(a);}}